	public static string BuildSource(Func<string, bool> typeExists, bool forceDesignTimePolyfills, string accessibility = "public")
	{
		StringBuilder stringBuilder = new StringBuilder();
		Entry[] entries = Entries;
		for (int i = 0; i < entries.Length; i++)
		{
			Entry entry = entries[i];
			if ((forceDesignTimePolyfills && entry.ForceInDesignTime) || !typeExists(entry.MetadataName))
			{
				stringBuilder.AppendLine((accessibility == "public") ? entry.Source : WithAccessibility(entry.Source, accessibility));
			}
		}
		return stringBuilder.ToString();
	}

	private static string WithAccessibility(string source, string accessibility)
	{
		return source.Replace("\tpublic readonly struct ", "\t" + accessibility + " readonly struct ").Replace("\tpublic enum ", "\t" + accessibility + " enum ").Replace("\tpublic static class ", "\t" + accessibility + " static class ")
			.Replace("\tpublic sealed class ", "\t" + accessibility + " sealed class ");
	}
}
